package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeSet;

/**
 * A rate for a grade on a sheet: a percent with two decimals, 0.00 or more, applying from its from-date (null: from
 * the beginning of time) through its to-date (null: with no end).
 */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal pct;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    /** The number of this, the newest version, counting from 1; the older ones are kept as {@link RateVersion}s. */
    @Column(name = "version", nullable = false)
    private int version = 1;

    /**
     * For a forward-only rate (one saved with a from-date on or after the sheet's today), the claim mark it was saved
     * at: it applies only to claims added after, those with a greater mark (see {@link #appliesTo}). Null for a rate
     * that applies to every claim.
     */
    @Column(name = "after_mark")
    private Long afterMark;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate from, BigDecimal pct) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.pct = pct;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public void setTo(LocalDate to) {
        this.to = to;
    }

    public int getVersion() {
        return version;
    }

    public Long getAfterMark() {
        return afterMark;
    }

    public void setAfterMark(Long afterMark) {
        this.afterMark = afterMark;
    }

